# SPDX-License-Identifier: AGPL-3.0-only
import heapq

def solve(payload):
    graph = {node: [] for node in payload["nodes"]}
    for start, end, weight in payload["edges"]:
        graph[start].append((end, weight))
    initial = (0, 0, (payload["start"],))
    best = {payload["start"]: initial}
    queue = [initial]
    while queue:
        cost, hops, path = heapq.heappop(queue)
        node = path[-1]
        if best[node] != (cost, hops, path):
            continue
        if node == payload["target"]:
            return {"cost": cost, "path": list(path)}
        for end, weight in graph[node]:
            candidate = (cost + weight, hops + 1, path + (end,))
            if end not in best or candidate[0] < best[end][0]:
                best[end] = candidate
                heapq.heappush(queue, candidate)
    return {"cost": None, "path": []}

